<!-- 视频分析 -->
<template>
  <div class="video-container">
    <div class="left">
      <el-tabs v-model="activeName">
        <el-tab-pane label="" name=""></el-tab-pane>
        <el-tab-pane label="实时视频" name="preview"></el-tab-pane>
        <el-tab-pane label="历史回放" name="playback"></el-tab-pane>
      </el-tabs>
      <div class="search_form">
        <el-form :model="queryParams" ref="form" label-position="top" :rules="rules">
          <el-form-item label="算法包" prop="model_id">
            <el-select v-model="queryParams.model_id" placeholder="请选择算法包" @change="handleChangeSf(queryParams.model_id)" clearable filterable style="width: 100%">
              <el-option v-for="item in options3" :key="item.id" :label="item.algorithm_name" :value="item.id"> </el-option>
            </el-select>
          </el-form-item>
          <el-form-item label="检测类型" prop="algorithm_test_type">
            <el-select v-model="queryParams.algorithm_test_type" placeholder="请选择检测类型" multiple clearable filterable style="width: 100%">
              <el-option v-for="item in options4" :key="item.id" :label="item.test_type_cname" :value="item.id"> </el-option>
            </el-select>
          </el-form-item>
          <el-form-item label="开始时间" v-if="activeName == 'playback'" prop="start_time">
            <el-date-picker popper-class="elDatePicker" v-model="queryParams.start_time" type="datetime" placeholder="选择开始时间" :picker-options="datePickerOptions" format='yyyy-MM-dd HH:mm:ss' value-format="yyyy-MM-dd HH:mm:ss" style="width: 100%;height: 33px;">
            </el-date-picker>
          </el-form-item>
          <el-form-item label="结束时间" v-if="activeName == 'playback'" prop="end_time">
            <el-date-picker popper-class="elDatePicker" v-model="queryParams.end_time" type="datetime" placeholder="选择结束时间" :picker-options="datePickerOptions" format='yyyy-MM-dd HH:mm:ss' value-format="yyyy-MM-dd HH:mm:ss" style="width: 100%;height: 33px;">
            </el-date-picker>
          </el-form-item>
        </el-form>
      </div>
      <div class="title1">
        录像机
      </div>
      <div class="search_place">
        <el-menu class="el-menu-vertical-demo">
          <template v-for="item in HKmenu">
            <el-submenu v-if="item.hasOwnProperty('children')" :index="item" :key="item.id">
              <template slot="title">{{ item.equipment_name }}</template>
              <template v-for="item1 in item.children">
                <el-menu-item :index="item1.id" @click="hadnleChangeMKmenu(item1)" :key="item1.id+'1'" :style="{ color: item1.online == 1 ? '' : 'gray', }">
                  {{ item1.equipment_name }}
                </el-menu-item>
              </template>
            </el-submenu>
            <el-menu-item v-else :index="item.id" @click="hadnleChangeMKmenu(item)" :key="item.id+'1'" :style="{ color: item.online == 1 ? '' : 'gray', }">
              {{ item.equipment_name }}
            </el-menu-item>
          </template>
        </el-menu>
      </div>
    </div>
    <div class="right">
      <div class="right_top">
        <div class="search-form">
          <el-form :rules="rules" label-width="100px">

            <!-- <el-form-item label="视频分辨率" prop="resolution">
              <div class="resolution-group">
                <el-input-number v-model="queryParams.resolution.width" :min="0" placeholder="宽度" style="width: 160px; margin-right: 4%;"></el-input-number>
                <span>x</span>
                <el-input-number v-model="queryParams.resolution.height" :min="0" placeholder="高度" style="width: 160px; margin-left: 4%;"></el-input-number>
              </div>
            </el-form-item>

            <el-form-item label="输出视频帧率" label-width="120px" prop="frameRate">
              <el-input-number v-model="queryParams.frameRate" :min="1" :max="60" placeholder="帧率" style="width: 140px;"></el-input-number>
            </el-form-item>

            <el-form-item label="视频比特率 (Kbps)" label-width="140px" prop="bitRate">
              <el-input-number v-model="queryParams.bitRate" :min="1" placeholder="比特率 (Kbps)" style="width: 140px;"></el-input-number>
            </el-form-item> -->

            <el-form-item label-width="10px">
              <el-button type="primary" icon="el-icon-video-camera" @click="handleSearch">播放</el-button>
              <el-button type="primary" icon="el-icon-circle-close" @click="stopVideo">停止</el-button>
            </el-form-item>
          </el-form>
        </div>
      </div>
      <div class="right_bottom" v-loading="videoLoading" element-loading-text="视频加载中" element-loading-spinner="el-icon-loading" element-loading-background="rgba(0, 0, 0, 0.8)">
        <video ref="videoPlayer" width="100%" v-if="spfxSrcFlv" height="100%" autoplay muted :src="spfxSrcFlv"></video>
        <video ref="videoPlayer" width="100%" v-else height="100%" autoplay muted :src="spfxSrc"></video>
      </div>
    </div>
  </div>
</template>
<script>
import flvjs from 'flv.js';
import { spfxApi } from '@/api/spfx';

export default {
  name: 'Spfx',
  data() {
    return {
      HKmenu: [],
      queryParams: {
        monitorPoint: '',
        resolution: {
          width: 1920,
          height: 1080
        },
        frameRate: 25,
        bitRate: 1000,
        start_time: null,
        end_time: null,
        em_id: null,
        model_id: null,
        algorithm_test_type: null,
      },
      rules: {
        frameRate: [
          { type: 'number', min: 1, max: 25, message: '帧率范围为 1 至 25', trigger: 'blur' }
        ],
        bitRate: [
          { type: 'number', min: 1, message: '比特率必须大于 0', trigger: 'blur' }
        ],
        model_id: [
          { required: true, message: '请选择算法包', trigger: 'change' }
        ],
        start_time: [
          { required: true, message: '请选择开始时间', trigger: 'blur' }
        ],
        end_time: [
          { required: true, message: '请选择结束时间', trigger: 'blur' },
          {
            validator: this.validateEndTime,
            trigger: 'blur'
          }
        ]
      },
      activeName: 'preview',
      options3: [],
      options4: [],
      interTime: null,
      spfxSrc: '/static/img/video/AIspfx.mp4',
      spfxSrcFlv: '',
      videoLoading: false,
      flvPlayer: null,
      isFlvMode: false, // 标记当前是否是FLV模式
    }
  },
  created() {
    this.getListPlace();
    this.$http
      .get(
        this.$url.url_5000 + "/model_view/type_select",
        {
          params: {},
        },
        {
          withCredentials: true,
        }
      )
      .then((response) => {
        this.options3 = response.data.algorithm_list;
      })
      .catch(function (response) {
        console.log(response);
      });
  },
  mounted() {
    // 初始加载MP4
    this.playMp4Video();
  },
  beforeDestroy() {
    this.stopVideo();
    clearInterval(this.interTime);
  },
  destroyed() {
    this.stopVideo();
    clearInterval(this.interTime);
  },
  methods: {
    validateEndTime(rule, value, callback) {
      if (this.queryParams.start_time && value) {
        if (new Date(this.queryParams.start_time) >= new Date(value)) {
          callback(new Error('结束时间必须在开始时间之后'));
        } else {
          callback();
        }
      } else {
        callback();
      }
    },
    handleChangeSf(id) {
      this.queryParams.algorithm_test_type = '';
      this.$http
        .get(this.$url.url_5000 + "/model_view/Algorithm_type_select", {
          params: { id },
        })
        .then((response) => {
          this.options4 = response.data.data.algorithm_data;
        })
        .catch((rek) => {
          console.log(rek);
        });
    },

    // 统一的视频重置方法
    resetVideoElement() {
      const video = this.$refs.videoPlayer;
      if (!video) return;
      
      // 暂停播放
      video.pause();
      
      // 移除所有事件监听器（如果有）
      // 清空src
      video.removeAttribute('src');
      // 重置加载状态
      video.load();
      // 清空当前播放源
      video.src = '';
      video.load();
    },

    // 播放FLV视频
    playFlvVideo(url) {
      // 先销毁旧的FLV播放器
      if (this.flvPlayer) {
        try {
          this.flvPlayer.destroy();
        } catch (error) {
          console.log('销毁播放器时出错:', error);
        }
        this.flvPlayer = null;
        this.isFlvMode = false;
      }

      // 重置视频元素
      this.resetVideoElement();

      // 检查浏览器是否支持 FLV.js
      if (flvjs.isSupported()) {
        const videoElement = this.$refs.videoPlayer;
        
        // 创建新的 FLV 播放器实例
        this.flvPlayer = flvjs.createPlayer({
          type: 'flv',
          url: url,
        });

        // 将播放器绑定到视频元素
        this.flvPlayer.attachMediaElement(videoElement);

        // 开始加载和播放
        this.flvPlayer.load();
        this.flvPlayer.play();
        this.isFlvMode = true;
      } else {
        this.$message.warning('浏览器不支持 FLV.js');
      }
    },

    // 播放MP4视频
    playMp4Video() {
      // 如果有FLV播放器，先销毁
      if (this.flvPlayer) {
        try {
          this.flvPlayer.destroy();
        } catch (error) {
          console.log('销毁播放器时出错:', error);
        }
        this.flvPlayer = null;
        this.isFlvMode = false;
      }

      const videoElement = this.$refs.videoPlayer;
      if (!videoElement) return;

      // 重置视频元素
      this.resetVideoElement();

      // 使用nextTick确保DOM更新完成
      this.$nextTick(() => {
        // 设置MP4源
        videoElement.src = this.spfxSrc;
        // 加载视频
        videoElement.load();
        // 播放视频
        videoElement.play().catch(error => {
          console.log('MP4播放失败:', error);
        });
      });
    },

    // 获取视频
    getVideo() {
      this.videoLoading = true;
      
      this.$http.get(spfxApi.getPlayInfo, {
        params: {
          rtsp_url: this.queryParams.monitorPoint,
          model_id: this.queryParams.model_id,
          algorithm_test_type: this.queryParams.algorithm_test_type,
          width: this.queryParams.resolution.width,
          height: this.queryParams.resolution.height,
          baud_b: this.queryParams.bitRate,
          frame_r: this.queryParams.frameRate,
          det_type: 3,
          stream_data_flag: 1,
          em_id: JSON.stringify([this.queryParams.em_id]),
          video_status: this.activeName == 'preview' ? 1 : 2,
          start_time: this.activeName == 'playback' ? this.formatDate(this.queryParams.start_time) : null,
          end_time: this.activeName == 'playback' ? this.formatDate(this.queryParams.end_time) : null,
        }
      }).then(response => {
        if (response.data.code === 200) {
          this.$message.success(response.data.msg);
          this.spfxSrcFlv = response.data.flv_data[0].flv_url;
          
          // 播放FLV
          this.playFlvVideo(this.spfxSrcFlv);
          
          // 轮询状态
          clearInterval(this.interTime);
          this.interTime = setInterval(() => {
            this.getFlvStatus();
          }, 1000);
          
          setTimeout(() => {
            this.videoLoading = false;
          }, 3000);
        } else {
          this.videoLoading = false;
        }
      }).catch(rek => {
        console.log(rek);
        this.videoLoading = false;
      });
    },

    // 获取flv状态
    getFlvStatus() {
      this.$http.get(spfxApi.getFlvStatus)
        .then(response => {
          if (response.data.code == 200) {
            clearInterval(this.interTime);
            setTimeout(() => {
              if (this.isFlvMode && this.flvPlayer) {
                // 如果还在FLV模式下，重新播放
                this.playFlvVideo(this.spfxSrcFlv);
              }
              this.videoLoading = false;
            }, 3000);
          }
        })
        .catch(rek => {
          console.log(rek);
        });
    },

    formatDate(input) {
      return input.replace(/(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})/, '\$1\$2\$3t\$4\$5\$6');
    },

    // 获取监控点列表
    getListPlace() {
      this.$http
        .get(this.$url.url_5000 + "/model_view/equipment_show", {
          params: {
            equipment_name: '',
            equipment_type: '',
            page: 1,
            per_page: 999999999,
          },
        })
        .then((response) => {
          if (response.data.code === 200) {
            this.HKmenu = response.data.data_list.data;
          }
        })
        .catch(function (response) {
          console.log(response);
        });
    },

    hadnleChangeMKmenu(item) {
      if (item.equipment_type == '录像机') {
        if (item.online == 1) {
          this.queryParams.monitorPoint = item.rtsp;
          this.queryParams.em_id = item.id;
        } else {
          this.queryParams.monitorPoint = '';
          this.queryParams.em_id = '';
          this.$message({
            type: 'warning',
            message: '该监控点不在线,请选择其他监控点!'
          });
        }
      } else {
        this.queryParams.monitorPoint = item.rtsp;
        this.queryParams.em_id = item.id;
      }
    },

    handleSearch() {
      this.$refs.form.validate((valid) => {
        if (valid) {
          if (this.queryParams.monitorPoint == '') {
            this.$message({
              type: 'warning',
              message: '请选择监控点'
            });
            return;
          }
          // 先停止当前播放再开始新的
          this.stopVideo();
          // 延迟一下再请求
          setTimeout(() => {
            this.getVideo();
          }, 300);
        } else {
          console.log('表单验证失败');
          return false;
        }
      });
    },

    // 停止视频
    stopVideo() {
      // 清除定时器
      clearInterval(this.interTime);
      
      // 如果正在FLV模式
      if (this.isFlvMode) {
        if (this.flvPlayer) {
          try {
            this.flvPlayer.destroy();
          } catch (error) {
            console.log('销毁播放器时出错:', error);
          }
          this.flvPlayer = null;
        }
        this.isFlvMode = false;
        this.videoLoading = false;
        this.spfxSrcFlv = '';
      }

      // 切换到MP4播放
      this.playMp4Video();
    }
  }
}
</script>

